'use client';

import { useEffect, useState } from 'react';

export default function DashboardPage() {
  const [status, setStatus] = useState<any>(null);
  const [agents, setAgents] = useState<any[]>([]);
  const [rotating, setRotating] = useState(false);

  useEffect(() => {
    const fetchAll = async () => {
      const [statusRes, agentsRes] = await Promise.all([
        fetch('/api/brain/status').then(r => r.json()),
        fetch('/api/agents?limit=50').then(r => r.json()),
      ]);
      if (statusRes.success) setStatus(statusRes.data);
      if (agentsRes.success) setAgents(agentsRes.data.agents);
    };
    fetchAll();
    const interval = setInterval(fetchAll, 5000);
    return () => clearInterval(interval);
  }, []);

  const triggerRotation = async () => {
    setRotating(true);
    const adminKey = prompt('Enter admin key:');
    if (!adminKey) { setRotating(false); return; }

    const res = await fetch('/api/brain/rotate', {
      method: 'POST',
      headers: { 'x-admin-key': adminKey },
    });
    const json = await res.json();
    if (json.success) alert(json.data.message);
    else alert(`Error: ${json.error}`);
    setRotating(false);
  };

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold">Dashboard</h1>
        <button
          onClick={triggerRotation}
          disabled={rotating}
          className="rounded-lg bg-amber-500 text-black px-4 py-2 font-semibold hover:bg-amber-400 disabled:opacity-50 transition-colors"
        >
          {rotating ? 'Rotating...' : 'Trigger Rotation'}
        </button>
      </div>

      {status && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
          <Stat label="Total Agents" value={status.stats.agents} />
          <Stat label="Sensors" value={status.stats.sensors} color="text-blue-400" />
          <Stat label="Actuators" value={status.stats.actuators} color="text-rose-400" />
          <Stat label="Interneuron" value={status.currentInterneuron?.name || 'None'} color="text-amber-400" />
          <Stat label="Total Signals" value={status.stats.signals} />
          <Stat label="Total Directives" value={status.stats.directives} />
          <Stat label="Pending Signals" value={status.stats.pendingSignals} />
          <Stat label="Rotations" value={status.rotationCount} />
        </div>
      )}

      <div>
        <h2 className="text-xl font-bold mb-4">All Agents</h2>
        <div className="space-y-2">
          {agents.map((a: any) => (
            <a
              key={a._id}
              href={`/agents/${a.name}`}
              className="flex items-center justify-between rounded-lg border border-neutral-800 bg-neutral-900 p-4 hover:border-neutral-600 transition-colors"
            >
              <div className="flex items-center gap-3">
                <span className={`w-3 h-3 rounded-full ${
                  a.role === 'sensor' ? 'bg-blue-500' :
                  a.role === 'actuator' ? 'bg-red-500' : 'bg-amber-500'
                }`} />
                <span className="font-semibold">{a.name}</span>
                <span className="text-neutral-500 text-sm">{a.description}</span>
              </div>
              <div className="flex items-center gap-3 text-xs">
                <span className={`rounded-full px-2 py-0.5 ${
                  a.role === 'sensor' ? 'bg-blue-500/20 text-blue-400' :
                  a.role === 'actuator' ? 'bg-red-500/20 text-red-400' : 'bg-amber-500/20 text-amber-400'
                }`}>{a.role}</span>
                <span className={a.claimStatus === 'claimed' ? 'text-green-400' : 'text-neutral-500'}>
                  {a.claimStatus}
                </span>
              </div>
            </a>
          ))}
        </div>
      </div>
    </div>
  );
}

function Stat({ label, value, color }: { label: string; value: string | number; color?: string }) {
  return (
    <div className="rounded-lg border border-neutral-800 bg-neutral-900 p-4">
      <div className="text-xs text-neutral-500 uppercase tracking-wider">{label}</div>
      <div className={`mt-1 text-xl font-bold ${color || 'text-white'}`}>{value}</div>
    </div>
  );
}
